import React, { useRef } from 'react';
import { useDrag, useDrop } from 'react-dnd';

// Define the type of item being dragged (MUST be unique string)
const ItemType = 'CONTENT_ITEM';

function DraggableItem({ item, index, moveItem, children }) {
  const ref = useRef(null);

  // The unique ID used for the database operation (item.position in your case)
  const id = item.id; 

  // 1. useDrag: Makes the item movable
  const [{ isDragging }, drag] = useDrag({
    type: ItemType,
    item: () => ({ id, index }), // Data passed when dragging starts
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  });

  // 2. useDrop: Makes the item a target
  const [, drop] = useDrop({
    accept: ItemType,
    hover(draggedItem, monitor) {
      if (!ref.current) {
        return;
      }
      const dragIndex = draggedItem.index;
      const hoverIndex = index;

      // Don't replace items with themselves
      if (dragIndex === hoverIndex) {
        return;
      }

      // Perform the move logic immediately in the local state
      moveItem(dragIndex, hoverIndex);

      // Mutate the dragged item's index to reflect the movement
      // This is crucial for performance and continuity in react-dnd
      draggedItem.index = hoverIndex;
    },
  });

  // Attach drag and drop ref to the DOM node
  drag(drop(ref));

  const opacity = isDragging ? 0 : 1;
  const style = {
      opacity,
      cursor: 'move',
      padding: '10px',
      border: '1px solid #ccc',
      marginBottom: '8px',
      backgroundColor: 'white'
  };

  return (
    <div ref={ref} style={style}>
      {/* Render the content passed as children */}
      {children}
    </div>
  );
}

export default DraggableItem;
